sys_variable_value.value:
(function execute(inputs, outputs) {

    var currentRecord = inputs.currentRecord;

var companycode = currentRecord.variables.company_code.getDisplayValue();
var contractNumber = currentRecord.variables.numero_da_solicitacao_original.getDisplayValue();
var validade = currentRecord.variables.data_de_inicio_do_aditivo.getDisplayValue();
var fomattedDate = formatDateToDDMMYYYY(validade);

var mrvs = currentRecord.variables.art_fiador;
var totalRows = mrvs.getRowCount();

var conditionObj = {
    "CompanyCode": companycode,
    "ContractNumber": contractNumber,
    "BusinessPartners": []
};

for (var i = 0; i < totalRows; i++) {

    var possuiBp = mrvs.getRow(i).getCell('cliente_possui_cadastro_no_sap_fiador').getCellValue();
    var tipo = mrvs.getRow(i).getCell('fiador__tipo_de_pessoa').getCellValue();
    gs.info(tipo);

	var cnpjfiador = mrvs.getRow(i).getCell('fiador__cnpj_do_locatario').getCellValue();
	var cnpjFormatado = cnpjfiador.replace(/[.\-/]/g, '');
	gs.info(cnpjFormatado);
	var cpfFiador = mrvs.getRow(i).getCell('fiador__cpf_do_locatario').getCellValue();
	var cpfFormatado = cpfFiador.replace(/[.\-]/g, '');

    if (possuiBp == 'sim') {
        var numeroBp = mrvs.getRow(i).getCell('codigo_bp_fiador').getCellDisplayValue();
        //gs.info('Linha do For: ' + i);

        var myobj = {
            "BPNumber": numeroBp, //mudar esse 
            "BPRoleCode": "TR0200",
            "BPValidTo": fomattedDate
        };
        conditionObj.BusinessPartners.push(myobj);
    } else if (possuiBp == 'nao') {
        //gs.info('Linha do For: ' + i);
        gs.info('Fazer glide para buscar no filho após integração');

		if(tipo == 'juridica'){
			var juridico = getBPSapIntegration_Juridica(current.sys_id, cnpjFormatado);
		}else if(tipo == 'fisica'){
			var fisica = getBPSapIntegration_Fisica(currentRecord.sys_id, cpfFormatado);
		} else {
			gs.info('***Fiador: BP Não Selecionado');
			//outputs.tiponaoselecionado = true
		}



    } else {
        gs.info('***Fiador: BP Não Selecionado');
        outputs.bpnaoselecionado = true;
    }
}

function formatDateToDDMMYYYY(dateString) {
    var parts = dateString.split('/');
    var day = parts[0];
    var month = parts[1];
    var year = parts[2];

    return year + '-' + month + '-' + day;
}



function getBPSapIntegration_Juridica(id, cnpj) {

    var grRequestedItemCnpjFiador5 = new GlideRecord("x_asscs_allos_o2c_requested_item");
    grRequestedItemCnpjFiador5.addQuery("parent", id);
    grRequestedItemCnpjFiador5.addQuery("variables.e50394a1878c06901ee364640cbb356a", cnpj); // Filtro por CNPJ do fiador
    grRequestedItemCnpjFiador5.query();

    if (grRequestedItemCnpjFiador5.next()) {
        var grTaskCNPJFiador5 = new GlideRecord("x_asscs_allos_o2c_task");
        grTaskCNPJFiador5.addQuery("parent", grRequestedItemCnpjFiador5.sys_id.toString());
        grTaskCNPJFiador5.addQuery("order", 1);
        grTaskCNPJFiador5.query();

        if (grTaskCNPJFiador5.next()) {
            bpNumberFiador = grTaskCNPJFiador5.u_codigo_bp_sap_integration.toString();
			gs.info("bpNumberFiador" + bpNumberFiador);
            return bpNumberFiador;
        }
    }
}

function getBPSapIntegration_Fisica(id, cpf) {

    var grRequestedItemFiador5 = new GlideRecord("x_asscs_allos_o2c_requested_item");
    grRequestedItemFiador5.addQuery("parent", id);
    grRequestedItemFiador5.addQuery("variables.5b42ba99870006901ee364640cbb3562", cpf); // Filtro por CPF do fiador
    grRequestedItemFiador5.query();

    if (grRequestedItemFiador5.next()) {
        var grTaskFiador5 = new GlideRecord("x_asscs_allos_o2c_task");
        grTaskFiador5.addQuery("parent", grRequestedItemFiador5.sys_id.toString());
        grTaskFiador5.addQuery("order", 1);
        grTaskFiador5.query();

        if (grTaskFiador5.next()) {
            bpNumberFiador = grTaskFiador5.u_codigo_bp_sap_integration.toString();
			gs.info("bpNumberFiador" + bpNumberFiador);
            return bpNumberFiador;
        }
    }
}

gs.info('***Contratos Output: ' + JSON.stringify(conditionObj));

})(inputs, outputs);

